using Microsoft.AspNetCore.Authorization; using AshkanCMS.Data; using AshkanCMS.Models; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AshkanCMS.Areas.Admin.Controllers; [Area("Admin"),Authorize]
public class ContentController(AppDbContext db):Controller{public async Task<IActionResult> Categories()=>View(await db.Categories.Include(x=>x.Posts).ToListAsync()); public async Task<IActionResult> Pages()=>View(await db.Pages.ToListAsync()); public async Task<IActionResult> Comments()=>View(await db.Comments.OrderByDescending(x=>x.CreatedAt).ToListAsync()); public async Task<IActionResult> Media()=>View(await db.Media.OrderByDescending(x=>x.UploadedAt).ToListAsync()); public async Task<IActionResult> Settings(){return View(await db.Settings.FirstAsync());}[HttpPost]public async Task<IActionResult> Settings(SiteSetting s){db.Update(s);await db.SaveChangesAsync();return RedirectToAction(nameof(Settings));}}
